const bytes = require('fs').readFileSync('original/crypto-core.wasm');
const mod = new WebAssembly.Module(bytes);
const name = WebAssembly.Module.exports(mod).find(e => e.name.length < 120).name;
const run = new WebAssembly.Instance(mod).exports[name];
let cases = [[0,0],[-1,0],[2147483647,0],[-2147483648,0],[-2147483648,-1],[0,4294967295]];
let seed=42;
const next=()=>seed=(Math.imul(seed,1664525)+1013904223)|0;
for(let i=0;i<1000;i++)cases.push([next(),next()]);
console.log(JSON.stringify(cases.map(([a,b])=>[a,b,run(a,b)])));
JS"

